// Joystick ile pan-tilt: joystick iki servoyu döndürür, düğmesi ortalar.
#include <Servo.h>

const int X_PIN = A0;      // HORZ (VRx)
const int Y_PIN = A1;      // VERT (VRy)
const int BUTON_PIN = 2;   // SEL (SW)
const int PAN_PIN = 9;
const int TILT_PIN = 10;

const int OLU_BOLGE = 60;    // orta çevresinde yok sayılan oynama (0-512)
const int EN_HIZ = 3;        // her adımda en çok kaç derece
const int ADIM_SURESI = 20;  // ms
const int ORTA_ACI = 90;
const int TILT_MIN = 20;     // braket çarpmasın diye tilt sınırları
const int TILT_MAX = 160;
const bool PAN_TERS = false;   // ters dönerse true yap
const bool TILT_TERS = false;

Servo pan;
Servo tilt;
int panAci = ORTA_ACI;
int tiltAci = ORTA_ACI;

// Joystick okumasını (0-1023) derece/adım hızına çevirir.
int hizHesapla(int okuma, bool ters) {
  int sapma = okuma - 512;
  if (abs(sapma) < OLU_BOLGE) return 0;
  int hiz = map(abs(sapma), OLU_BOLGE, 512, 1, EN_HIZ);
  if (sapma < 0) hiz = -hiz;
  return ters ? -hiz : hiz;
}

void setup() {
  Serial.begin(9600);
  pinMode(BUTON_PIN, INPUT_PULLUP);
  pan.attach(PAN_PIN);
  tilt.attach(TILT_PIN);
  pan.write(panAci);
  tilt.write(tiltAci);
}

void loop() {
  int eskiPan = panAci;
  int eskiTilt = tiltAci;

  panAci = constrain(panAci + hizHesapla(analogRead(X_PIN), PAN_TERS), 0, 180);
  tiltAci = constrain(tiltAci + hizHesapla(analogRead(Y_PIN), TILT_TERS), TILT_MIN, TILT_MAX);

  // Düğme basılıysa ikisini de ortala.
  if (digitalRead(BUTON_PIN) == LOW) {
    panAci = ORTA_ACI;
    tiltAci = ORTA_ACI;
  }

  pan.write(panAci);
  tilt.write(tiltAci);

  if (panAci != eskiPan || tiltAci != eskiTilt) {
    Serial.print("Pan: ");
    Serial.print(panAci);
    Serial.print("  Tilt: ");
    Serial.println(tiltAci);
  }
  delay(ADIM_SURESI);
}
